// ─── Helpers ──────────────────────────────────────────────────────────────────

const INDEX_OPTIONS = [
  { symbol: 'AAPL',  label: 'Apple (AAPL)'   },
  { symbol: 'MSFT',  label: 'Microsoft (MSFT)'},
  { symbol: 'NVDA',  label: 'NVIDIA (NVDA)'  },
  { symbol: 'GOOGL', label: 'Alphabet (GOOGL)'},
  { symbol: 'TSM',   label: 'TSMC (TSM)'     },
  { symbol: 'ASML',  label: 'ASML (ASML)'    },
];

function groupByWeek(bars: DayBar[]): DayBar[][] {
  if (bars.length === 0) return [];
  // Find what weekday (Mon=1..Fri=5) each bar falls on
  const weeks: DayBar[][] = [];
  let currentWeek: DayBar[] = [];
  let prevWk = -1;

  bars.forEach((bar) => {
    const d = new Date(bar.date + 'T12:00:00Z');
    const wk = getISOWeek(d);
    if (wk !== prevWk && currentWeek.length > 0) {
      weeks.push(currentWeek);
      currentWeek = [];
    }
    currentWeek.push(bar);
    prevWk = wk;
  });
  if (currentWeek.length > 0) weeks.push(currentWeek);
  return weeks.slice(-8); // last 8 weeks max
}

function getISOWeek(d: Date): number {
  const tmp = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  tmp.setUTCDate(tmp.getUTCDate() + 4 - (tmp.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(tmp.getUTCFullYear(), 0, 1));
  return Math.ceil(((tmp.getTime() - yearStart.getTime()) / 86400000 + 1) / 7);
}

function weekdayIndex(dateStr: string): number {
  // Mon=0, Tue=1, Wed=2, Thu=3, Fri=4
  const d = new Date(dateStr + 'T12:00:00Z');
  const wd = d.getUTCDay(); // Sun=0..Sat=6
  return wd - 1; // Mon=0..Fri=4
}

function dayLabel(dateStr: string): string {
  return new Date(dateStr + 'T12:00:00Z').toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
}

// ─── Day cell with tooltip ────────────────────────────────────────────────────

function DayCellWithTooltip({ bar }: { bar: DayBar }) {
  const [hover, setHover] = useState(false);
  return (
    <DayCell
      bg={heatColor(bar.changePct)}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      {hover && (
        <TooltipBox>
          <div style={{ fontWeight: 600, marginBottom: 4 }}>{dayLabel(bar.date)}</div>
          <div>Open  {fmt(bar.open,  bar.open  > 100 ? 0 : 2)}</div>
          <div>Close {fmt(bar.close, bar.close > 100 ? 0 : 2)}</div>
          <div>High  {fmt(bar.high,  bar.high  > 100 ? 0 : 2)}</div>
          <div>Low   {fmt(bar.low,   bar.low   > 100 ? 0 : 2)}</div>
          <div style={{ marginTop: 4, color: bar.changePct >= 0 ? '#3fb950' : '#f85149', fontWeight: 600 }}>
            {fmtPct(bar.changePct)}
          </div>
        </TooltipBox>
      )}
      <DayDate>{dayLabel(bar.date)}</DayDate>
      <DayPct>{fmtPct(bar.changePct)}</DayPct>
    </DayCell>
  );
}

// ─── Component ────────────────────────────────────────────────────────────────

export default function MarketCalendar() {
  const [range, setRange]     = useState<'5d' | '1mo' | '3mo'>('1mo');
  const [symbol, setSymbol]   = useState('^GSPC');
  const { bars, loading }     = useHistory(symbol, range);

  const weeks = groupByWeek(bars);

  // Stats
  const upDays   = bars.filter((b) => b.changePct > 0);
  const downDays = bars.filter((b) => b.changePct < 0);
  const best     = bars.reduce((a, b) => a.changePct > b.changePct ? a : b, bars[0]);
  const worst    = bars.reduce((a, b) => a.changePct < b.changePct ? a : b, bars[0]);
  const totalChg = bars.length > 1
    ? ((bars[bars.length - 1].close - bars[0].close) / bars[0].close) * 100
    : 0;

  return (
    <Wrapper>
      <Header>
        <Title>
          <Calendar size={18} color="#e3b341" />
          Good &amp; Bad Days
        </Title>
        <Controls>
          <IndexSelect value={symbol} onChange={(e) => setSymbol(e.target.value)}>
            {INDEX_OPTIONS.map((o) => (
              <option key={o.symbol} value={o.symbol}>{o.label}</option>
            ))}
          </IndexSelect>
          {(['5d', '1mo', '3mo'] as const).map((r) => (
            <RangeBtn key={r} active={range === r} onClick={() => setRange(r)}>
              {r === '5d' ? '1W' : r === '1mo' ? '1M' : '3M'}
            </RangeBtn>
          ))}
        </Controls>
      </Header>

      <Body>
        <CalWrap>
          <DayHeaderRow>
            {['Mon', 'Tue', 'Wed', 'Thu', 'Fri'].map((d) => (
              <DayHeader key={d}>{d}</DayHeader>
            ))}
          </DayHeaderRow>

          {loading ? (
            Array.from({ length: 4 }).map((_, wi) => (
              <WeekRow key={wi}>
                {Array.from({ length: 5 }).map((_, di) => (
                  <SkeletonCell key={di} />
                ))}
              </WeekRow>
            ))
          ) : (
            weeks.map((week, wi) => {
              // Build a Mon–Fri grid, filling gaps with empty cells
              const cells: (DayBar | null)[] = [null, null, null, null, null];
              week.forEach((bar) => {
                const idx = weekdayIndex(bar.date);
                if (idx >= 0 && idx < 5) cells[idx] = bar;
              });
              return (
                <WeekRow key={wi}>
                  {cells.map((bar, di) =>
                    bar ? (
                      <DayCellWithTooltip key={di} bar={bar} />
                    ) : (
                      <DayCell key={di} bg="transparent" empty />
                    )
                  )}
                </WeekRow>
              );
            })
          )}

          <LegendRow style={{ marginTop: theme.spacing.sm }}>
            <span>−4%</span>
            <LegendBar />
            <span>+4%</span>
          </LegendRow>
        </CalWrap>

        <Sidebar>
          <StatCard>
            <StatTitle>Period Return</StatTitle>
            <StatValue positive={totalChg >= 0}>{fmtPct(totalChg)}</StatValue>
            <StatSub>{bars.length} trading days</StatSub>
          </StatCard>

          <StatCard>
            <StatTitle>Up Days</StatTitle>
            <StatValue positive>
              {upDays.length}
              <span style={{ fontSize: 13, fontWeight: 400, color: theme.colors.mainTextMuted }}>
                {' '}/ {bars.length}
              </span>
            </StatValue>
            <StatSub>
              {bars.length > 0 ? Math.round((upDays.length / bars.length) * 100) : 0}% of trading days
            </StatSub>
          </StatCard>

          <StatCard>
            <StatTitle>Down Days</StatTitle>
            <StatValue positive={false}>
              {downDays.length}
              <span style={{ fontSize: 13, fontWeight: 400, color: theme.colors.mainTextMuted }}>
                {' '}/ {bars.length}
              </span>
            </StatValue>
            <StatSub>
              {bars.length > 0 ? Math.round((downDays.length / bars.length) * 100) : 0}% of trading days
            </StatSub>
          </StatCard>

          {best && (
            <StatCard>
              <StatTitle>Best Day</StatTitle>
              <StatValue positive>
                <TrendingUp size={14} style={{ marginRight: 4 }} />
                {fmtPct(best.changePct)}
              </StatValue>
              <StatSub>{dayLabel(best.date)}</StatSub>
            </StatCard>
          )}

          {worst && (
            <StatCard>
              <StatTitle>Worst Day</StatTitle>
              <StatValue positive={false}>
                <TrendingDown size={14} style={{ marginRight: 4 }} />
                {fmtPct(worst.changePct)}
              </StatValue>
              <StatSub>{dayLabel(worst.date)}</StatSub>
            </StatCard>
          )}

          <StatCard>
            <StatTitle>How to read</StatTitle>
            <div style={{ fontSize: 11, color: theme.colors.mainTextMuted, lineHeight: 1.5 }}>
              Each cell is one trading day. Dark green = strong up day. Dark red = strong down day. Hover any cell for open, close, high, low, and % change.
            </div>
          </StatCard>
        </Sidebar>
      </Body>
    </Wrapper>
  );
}
